operation.expression:
let $input-xml := $input.request 


(: Reference data - unused in this example but kept :)
let $ReferenceOutput :=
  <root>
    <referenceprocess><Code>NL-BSN</Code><Name>BSN-BSN number</Name></referenceprocess>
    <referenceprocess><Code>NL-FI</Code><Name>FI-Financial Accounting (FI)</Name></referenceprocess>
    <referenceprocess><Code>NL-KVK</Code><Name>KVK-KVK Number</Name></referenceprocess>
    <referenceprocess><Code>NL-SI</Code><Name>SI-SI registration number</Name></referenceprocess>
    <referenceprocess><Code>NL-VAT</Code><Name>VAT-Intracommunitary VAT code</Name></referenceprocess>
  </root>

(: Default country code from input XML - not used here, kept for structure :)
let $Default_country_code := $input-xml/payload/BuCountry/text()

(: Logic to get distinct country codes from reference and flag - kept unchanged :)
let $DataEnrichLogic := 
  let $Reference_Country_code := fn:distinct-values(
    for $code in $ReferenceOutput//Code/text()
    return fn:substring-before($code, '-')
  )
  let $GenerateCodeNameFlag :=
    if (fn:contains($Reference_Country_code, $Default_country_code))
    then 'DefaultCountry'
    else 'DifferentCountry'
  return
    <referenceCheck>
      <referenceCountryCodes>{string-join($Reference_Country_code, ', ')}</referenceCountryCodes>
      <flagResult>{$GenerateCodeNameFlag}</flagResult>
    </referenceCheck>

return 
<BuOutputPerRecord>
  <docId>{$input-xml/docId/text()}</docId>
  <payload>
    <BuCountry>{$input-xml/payload/BuCountry/text()}</BuCountry>
    <LegalCountry>{$input-xml/payload/BuCountry/text()}</LegalCountry>

    {
      (: If flag is DefaultCountry and no ChildBrandInputPayload, generate output from ReferenceOutput :)
      if (($DataEnrichLogic/flagResult/text() = 'DefaultCountry') and (not(exists($input-xml/payload/ChildBrandInputPayload)))) then
        (
            <ChildFGOutletBrands>
              <BrandName>Default_Brand1</BrandName>
              <BrandCode>Default_Code1</BrandCode>
            </ChildFGOutletBrands>
        )
      else
        (
          (: Iterate over each ChildBrandInputPayload element :)
          for $item in $input-xml/payload/ChildBrandInputPayload
          return
            <ChildFGOutletBrands>
              <BrandName>{$item/BrandNames/text()}</BrandName>
              <BrandCode>{$item/BrandCode/text()}</BrandCode>
              <sys>{$item/sys/groupId/text()}</sys>
            </ChildFGOutletBrands>
        )
    }

    <sys>
      <groupId>{$input-xml/payload/sys/groupId/text()}</groupId>
    </sys>
  </payload>

  <validation>
    {
      (: Create combined keys: lowercase BrandName + '|' + BrandCode :)
      let $combinedKeys :=
        for $item in $input-xml/payload/ChildBrandInputPayload
        let $name := fn:lower-case($item/BrandNames)
        let $code := $item/BrandCode
        return concat($name, '|', $code)

      (: Find distinct keys that occur more than once :)
      let $duplicateKeys :=
        for $key in fn:distinct-values($combinedKeys)
        where count($combinedKeys[. = $key]) > 1
        return $key

      let $hasDuplicates := exists($duplicateKeys)

      (: Identify first groupId for any duplicate combination :)
      let $firstDuplicateGroupId := 
        if ($hasDuplicates) then
          (
            for $item in $input-xml/payload/ChildBrandInputPayload
            let $key := concat(fn:lower-case($item/BrandNames), '|', $item/BrandCode)
            where $key = $duplicateKeys[1]
            return $item/sys/groupId/text()
          )[1]
        else ()

      return (
        <passed>{ if ($hasDuplicates) then 'false' else 'true' }</passed>,
        if ($hasDuplicates) then
          <fields>
            <fieldName>BrandNames</fieldName>
            <sys><groupId>{$firstDuplicateGroupId}</groupId></sys>
          </fields>
        else ()
      )
    }
  </validation>
</BuOutputPerRecord>
